"""Offline regression cases for IR channel evidence and coverage semantics.

These are independent fixtures derived from observed survey failure modes,
not tests of whether the live issuers still expose the captured pages.
"""

from __future__ import annotations

import importlib.util
import json
import tempfile
import unittest
from pathlib import Path


SPEC = importlib.util.spec_from_file_location(
    "ir_universe_validation", Path(__file__).resolve().parents[1] / "scripts/validate_ir_universe.py"
)
assert SPEC is not None and SPEC.loader is not None
validation = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(validation)

STAMP = "2026-10-11T01:00:00+00:00"
QUESTION_FORM = {
    "text": "メールアドレス お問い合わせ内容",
    "controls": [{"tag": "input", "type": "email", "name": "email"},
                 {"tag": "textarea", "name": "message"}],
}


class SurveyRegressionTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name)
        (self.root / "evidence").mkdir()
        self.universe = {"1301": {"company_name": "Fixture株式会社", "market": "プライム（内国株式）"}}

    def source(self, name, *, text, url="https://issuer.co.jp/ir/contact", forms=None, links=None, title=""):
        source = {"requested_url": url, "url": url, "http_status": 200,
                  "text": text + " Fixture株式会社", "title": title, "headings": [],
                  "forms": forms or [], "links": links or [],
                  "submitted": False, "retrieved_at": STAMP}
        path = "evidence/" + name + ".json"
        (self.root / path).write_text(json.dumps(source), encoding="utf-8")
        quote = {"snapshot": path, "url": url, "retrieved_at": STAMP, "quote": text}
        return source, quote

    def record(self, entries, *, level="form_fields_verified", emails=None):
        return {"security_code": "1301", "company_name": "Fixture株式会社",
                "market": "プライム（内国株式）", "investigation_status": "confirmed",
                "verification_level": level, "contact_url": entries[-1]["url"],
                "channels": ["email"] if emails else ["form"], "public_ir_emails": emails or [],
                "individual_access": "not_stated", "outreach_suitability": "candidate",
                "attempted_at": STAMP, "completed_at": STAMP,
                "evidence": entries, "fetches": [{"snapshot": e["snapshot"]} for e in entries],
                "identity_status": "name_or_security_code_observed",
                "identity_matches": [{"snapshot": entries[0]["snapshot"]}],
                "manual_review_required": True}

    def check(self, record):
        validator = validation.SurveyValidator(self.root, self.universe)
        result = validator.validate_record(record, {"official_url": "https://issuer.co.jp/"})
        return result, validator

