    def finite_enterprise_personal_ir_fixture(self, family, mode="valid"):
        """Independent issuer fixtures keep the four observed native and financial-route families."""
        import copy
        data = self.finite_enterprise_personal_ir_fixture_data()
        key = {"enterprise":"7244", "financial":"7264", "organization":"7371", "personal":"7483"}[family]
        model = copy.deepcopy(data[key]); display = "別の発行体"
        self.universe["1301"]["company_name"] = display
        def reissuer(value):
            if isinstance(value,str):return value.replace(model["display"],display).replace("https://www.doshisha.co.jp/","https://issuer.co.jp/")
            if isinstance(value,list):return [reissuer(x) for x in value]
            if isinstance(value,dict):return {k:reissuer(v) for k,v in value.items()}
            return value
        form = reissuer(model["form"]); operation = reissuer(model["operation"]); policy = model["policy"]
        official = "https://issuer.co.jp/"
        home = {"url":official,"requested_url":official,"title":display + "株式会社","text":display + "株式会社","forms":[],"links":[],"headings":[]}
        sources = {"home":home}; entries=[]
        def entry(source,quote,**extra):
            e={"snapshot":source["snapshot"],"url":source["url"],"retrieved_at":STAMP,"quote":quote,**extra};entries.append(e);return e
        def add(name,url,title,text,forms=None,links=None):
            s={"url":url,"requested_url":url,"title":title,"text":text,"forms":forms or [],"links":links or [],"headings":[]};sources[name]=s;return s
        if family=="enterprise":
            target=official + "form/";home["title"]=display + "株式会社-Welcome to Ichikoh website-";home["text"]=home["title"]
