    def test_finite_enterprise_row_ir_rejects_changed_witness(self):
        for mode in self.finite_enterprise_personal_ir_negative_modes("enterprise"):
            with self.subTest(mode=mode):
                r=self.finite_enterprise_personal_ir_fixture("enterprise",mode);v=validation.SurveyValidator(self.root,self.universe);self.assertFalse(v.reviewed_ir_enterprise_row_category(r,v.evidence(r)))

