    def test_finite_enterprise_personal_ir_preserves_reply_and_restriction_policy(self):
        for family in ("enterprise","financial","organization","personal"):
            for mode,kind in [("no_reply_claim","reply_policy_basis"),("sample_email_claim","email_unattributed"),("restricted_claim","restricted_access")]:
                with self.subTest(family=family,mode=mode):
                    r=self.finite_enterprise_personal_ir_fixture(family,mode);v=validation.SurveyValidator(self.root,self.universe);v.validate_record(r,{"official_url":"https://issuer.co.jp/"});self.assertIn(kind,{x["kind"] for x in v.issues})

    def finite_public_investment_type_fixture(self, mode="valid"):
        """A different issuer uses the captured native/public investment-type witness."""
