        record=self.record(entries);record.update(company_name='別の発行体',official_url='https://issuer.co.jp/',contact_url=primary['url'],individual_access='explicit',manual_review_required=False,manual_review={'reviewer':'fixture','reviewed_at':STAMP,'notes':'Whole captured native IR form, personal investment type only; no submission.'},identity_matches=[{'snapshot':home['snapshot']}])
