    def finite_public_investment_type_negative_modes(self):
        modes=['wrong_issuer','wrong_company','wrong_contact','http_contact','no_review','naive_review','duplicate_fetch','method','get_method','action','missing_action','search_form_first','duplicate_form','full_index_bool','full_index_true','full_index_string','full_index_wrong','legacy_index_only','conflicting_index','missing_fullquote','short_fullquote','missing_audiencequote','missing_operationquote','audience_other_source','duplicate_full_text','parent_index_bool','parent_index_string','parent_index_wrong','missing_parentquote','parent_target','parent_href','parent_url','parent_label','faq_code','missing_identityquote','faq_financial_scope','personal_choice','audience_label','customer_purpose','privacy_only','operation_not_adjacent','no_personal_reply','IR_refusal','telephone_only','delay_guarantee','copy_restriction','mail_only','control_order']
        modes += ['source:'+which+':'+key for which in ('home','primary','faq') for key in ('url','requested_url','title','submitted','http_status','retrieved_at')]
        modes += ['fetch:'+key for key in ('url','final_url','http_status','retrieved_at','snapshot')]
        for i,c in enumerate([{'tag': 'input', 'type': 'text', 'name': '00N10000002L7hc', 'id': '00N10000002L7hc'}, {'tag': 'input', 'type': 'text', 'name': '00N10000002L7hh', 'id': '00N10000002L7hh'}, {'tag': 'input', 'type': 'text', 'name': '00N10000002L7hm', 'id': '00N10000002L7hm'}, {'tag': 'input', 'type': 'text', 'name': '00N10000002L7hr', 'id': '00N10000002L7hr'}, {'tag': 'input', 'type': 'text', 'name': 'company', 'id': 'company'}, {'tag': 'input', 'type': 'text', 'name': '00N5F0000070wZD', 'id': '00N5F0000070wZD'}, {'tag': 'select', 'name': '00N5F000006ps3A', 'id': '00N5F000006ps3A'}, {'tag': 'textarea', 'type': 'text', 'name': '00N5F000006YCrt', 'id': '00N5F000006YCrt'}, {'tag': 'input', 'type': 'text', 'name': '00N5F000006ptbN', 'id': '00N5F000006ptbN'}, {'tag': 'input', 'type': 'text', 'name': 'mail_chk', 'id': 'mail_chk'}, {'tag': 'input', 'type': 'text', 'name': '00N10000002L7iu', 'id': '00N10000002L7iu'}, {'tag': 'input', 'type': 'checkbox', 'name': 'chk1', 'id': 'chk1_checkbox'}]):
            for k in c:modes.append(f'control:{i}:{k}:DELETE')
            modes.extend([f'control:{i}:type:hidden',f'control:{i}:name:another',f'control:{i}:required:NULL',f'control:{i}:value:0'])
        return modes

    def test_finite_public_investment_type_same_native_form(self):
        r=self.finite_public_investment_type_fixture();v=validation.SurveyValidator(self.root,self.universe)
        self.assertTrue(v.reviewed_ir_public_investment_type(r,v.evidence(r)))
        result=v.validate_record(r,{'official_url':'https://issuer.co.jp/'})
        self.assertEqual(v.issues,[]);self.assertTrue(result['channel_verified']);self.assertEqual(result['individual_access'],'explicit')

    def test_finite_public_investment_type_rejects_borrowed_or_changed_witness(self):
        for mode in self.finite_public_investment_type_negative_modes():
            with self.subTest(mode=mode):
                r=self.finite_public_investment_type_fixture(mode);v=validation.SurveyValidator(self.root,self.universe)
                self.assertFalse(v.reviewed_ir_public_investment_type(r,v.evidence(r)))

    def test_finite_public_investment_type_does_not_guarantee_reply_or_reclassify_restrictions(self):
        for mode,kind in [('no_reply_claim','reply_policy_basis'),('sample_email_claim','email_unattributed'),('restricted_claim','restriction_basis')]:
            with self.subTest(mode=mode):
                r=self.finite_public_investment_type_fixture(mode);v=validation.SurveyValidator(self.root,self.universe)
                v.validate_record(r,{'official_url':'https://issuer.co.jp/'})
                self.assertIn(kind,{i['kind'] for i in v.issues})

