    def test_finite_financial_menu_keeps_personal_and_reply_claims_limited(self):
        for family in ('child','holdings','occupation','investor','repeat'):
            with self.subTest(family=family):
                record=self.finite_financial_menu_and_personal_ir_fixture(family,'no_reply')
                _,_,v=self.check_finite_financial_menu_and_personal_ir(family,record)
                self.assertIn('reply_policy_basis',{i['kind'] for i in v.issues})
        for family in ('child','repeat'):
            with self.subTest(individual=family):
                record=self.finite_financial_menu_and_personal_ir_fixture(family,'individual_overclaim')
                accepted,_,v=self.check_finite_financial_menu_and_personal_ir(family,record)
                self.assertIs(accepted,False)
                self.assertIn('individual_access_basis',{i['kind'] for i in v.issues})
        record=self.finite_financial_menu_and_personal_ir_fixture('repeat','privacy_email')
        _,_,v=self.check_finite_financial_menu_and_personal_ir('repeat',record)
        self.assertIn('email_unattributed',{i['kind'] for i in v.issues})
        record=self.finite_financial_menu_and_personal_ir_fixture('occupation')
        accepted,_,_=self.check_finite_financial_menu_and_personal_ir('occupation',record)
        self.assertIs(accepted,True)
        source=json.loads((self.root/record['evidence'][-1]['snapshot']).read_text())
        self.assertEqual(source['forms'][0]['method'],'get')
        self.assertIsNone(source['forms'][0]['action'])

