    def check_finite_route_and_personal_ir(self, family, record):
        v=validation.SurveyValidator(self.root,self.universe);pairs=v.evidence(record)
        handler={'consent':v.reviewed_ir_consent_two_hop_form,'group':v.reviewed_ir_group_destination_form,
                 'shareholder':v.reviewed_ir_shareholder_intent_audience,'operation':v.reviewed_ir_japanese_reply_operation,
                 'audience':v.reviewed_ir_personal_and_recruitment_choice}[family]
        accepted=handler(record,pairs);result=v.validate_record(record,{'official_url':'https://issuer.co.jp/'})
        return accepted,result,v

    def test_finite_route_and_personal_ir_consent(self):
        record=self.finite_route_and_personal_ir_fixture('consent')
        accepted,result,v=self.check_finite_route_and_personal_ir('consent',record)
        self.assertIs(accepted,True)
        self.assertEqual(v.issues,[])
        self.assertTrue(result['channel_verified'])
        self.assertEqual(result['individual_access'],'not_stated')

