    def test_finite_routes_keep_topic_reply_and_personal_constraints_separate(self):
        for family in ('consent','group','shareholder','operation','audience'):
            with self.subTest(family=family):
                record=self.finite_route_and_personal_ir_fixture(family,'no_reply')
                _,result,v=self.check_finite_route_and_personal_ir(family,record)
                self.assertFalse(result['channel_verified'])
                self.assertIn('reply_policy_basis',{i['kind'] for i in v.issues})
        for family in ('consent','group','operation'):
            with self.subTest(individual=family):
                record=self.finite_route_and_personal_ir_fixture(family,'individual_overclaim')
                accepted,result,v=self.check_finite_route_and_personal_ir(family,record)
                self.assertIs(accepted,False)
                self.assertFalse(result['channel_verified'])
                self.assertIn('individual_access_basis',{i['kind'] for i in v.issues})
        record=self.finite_route_and_personal_ir_fixture('audience','sample_email')
        _,result,v=self.check_finite_route_and_personal_ir('audience',record)
        self.assertFalse(result['channel_verified'])
        self.assertIn('email_unattributed',{i['kind'] for i in v.issues})

