    def test_scoped_ir_meetings_do_not_claim_general_outreach_or_personal_limits(self):
        for mode in ("claimed_candidate","claimed_individual","claimed_restricted","claimed_no_reply"):
            with self.subTest(mode=mode):
                record = self.scoped_operation_ir_fixture("meeting", mode)
                supported, result, validator = self.check_scoped_operation_ir("meeting", record)
                self.assertIs(supported, False)
                self.assertFalse(result["channel_verified"])
                self.assertIn("form_level", {i["kind"] for i in validator.issues})

    def test_scoped_ir_topic_exclusions_do_not_become_general_no_reply_or_email_audience(self):
        for family in ("civil","email","privacy"):
            with self.subTest(family=family):
                record = self.scoped_operation_ir_fixture(family, "claimed_no_reply")
                _, result, validator = self.check_scoped_operation_ir(family, record)
                self.assertFalse(result["channel_verified"])
                self.assertIn("reply_policy_basis", {i["kind"] for i in validator.issues})
        record = self.scoped_operation_ir_fixture("email", "claimed_individual")
        supported, result, validator = self.check_scoped_operation_ir("email", record)
        self.assertIs(supported, False)
        self.assertFalse(result["channel_verified"])
        self.assertIn("individual_access_basis", {i["kind"] for i in validator.issues})

