    def test_robots_and_circuit_wrappers_are_terminal_but_not_content_get_coverage(self):
        for error in ["robots_disallowed", "robots_access_denied_stopped", "robots_unreachable_stopped", "environment_circuit_breaker_open"]:
            with self.subTest(error=error):
                source, quote = self.source("blocked", text=error)
                source.update(http_status=None, error=error)
                (self.root / quote["snapshot"]).write_text(json.dumps(source), encoding="utf-8")
                record = self.record([quote]); record.update(investigation_status="unconfirmed", verification_level="none",
                                                            outreach_suitability="unconfirmed", evidence=[])
                result, _ = self.check(record)
                self.assertTrue(result["terminal"])
                self.assertFalse(result["official_get_attempted"])
                self.assertFalse(result["channel_verified"])

    def test_failed_robots_actual_get_does_not_claim_company_content_or_ir_verification(self):
        source, quote = self.source("unreachable_robots", text="")
        source.update(http_status=None, text="", http_get_attempted=False, error="robots_unreachable_stopped",
                      robots={"url": "https://issuer.co.jp/robots.txt", "http_status": 503,
                              "http_get_attempted": True, "http_get_started_at": STAMP,
                              "retrieved_at": STAMP, "failure_signature": "common_transport_503",
                              "submitted": False, "text": "Invalid argument|remote address:envoy://cloudflare_"})
        path = self.root / quote["snapshot"]; path.write_text(json.dumps(source), encoding="utf-8")
        record = self.record([quote]); record.update(investigation_status="unconfirmed", verification_level="none",
                                                    outreach_suitability="unconfirmed", channels=[], evidence=[])
        before = path.read_bytes()
        result, validator = self.check(record)
        self.assertEqual([], validator.issues)
        self.assertTrue(result["terminal"])
        self.assertFalse(result["official_get_attempted"])
        self.assertFalse(result["channel_verified"])
        self.assertEqual(before, path.read_bytes())

