    @staticmethod
    def reviewed(record):
        record["manual_review_required"] = False
        record["manual_review"] = {"reviewed_at": STAMP, "reviewer": "fixture_review",
                                   "notes": "Public labels, actual controls, and the specific IR route were inspected."}
        return record

