    def test_individual_investor_audience_requires_exact_quoted_ir_link(self):
        label = "投資家向け情報（IR）について 経営方針、財務情報、IR資料、当社事業へのご質問"
        audience = "機関投資家、個人投資家、報道機関の皆様 "
        target = "https://issuer.co.jp/contact/ir?kind=ir"
        parent_source, parent = self.source("audience", text=audience + label, title="お問い合わせ",
                                            url="https://issuer.co.jp/contact",
                                            links=[{"url": target, "label": label}])
        parent["source_link_url"] = target
        _, actual = self.source("audience_ir", text="IRに関するお問い合わせ専用フォームです。 " + QUESTION_FORM["text"],
                                title="IRに関するお問い合わせ", url=target, forms=[QUESTION_FORM])
        record = self.record([parent, actual]); record["individual_access"] = "explicit"
        self.assertFalse(self.check(record)[0]["channel_verified"])
        result, validator = self.check(self.reviewed(record))
        self.assertTrue(result["channel_verified"], validator.issues)
        for change in ("declared_target", "captured_target", "navigation", "uncited_audience"):
            with self.subTest(change=change):
                source = {**parent_source, "links": [dict(parent_source["links"][0])]}
                citation = dict(parent)
                if change == "declared_target":
                    citation["source_link_url"] = "https://issuer.co.jp/contact/ir?kind=product"
                if change == "captured_target":
                    source["links"][0]["url"] = "https://issuer.co.jp/contact/ir?kind=product"
                if change == "navigation":
                    source["text"] = audience.rstrip() + "へ " + label + " Fixture株式会社"
                    citation["quote"] = audience.rstrip() + "へ " + label
                if change == "uncited_audience":
                    citation["quote"] = label
                (self.root / parent["snapshot"]).write_text(json.dumps(source), encoding="utf-8")
                record["evidence"] = [citation, actual]
                _, validator = self.check(record)
                self.assertIn("individual_access_basis", [issue["kind"] for issue in validator.issues])

