    def test_whitespace_in_recruitment_exclusion_preserves_specific_ir_mail(self):
        direction = "本ホームページの内容（IR情報等）に関するお問い合わせは、以下のご連絡先宛てにお願いいたします。"
        exclusion = "なお、採用に関するお問い合わせは、 採用情報のページ をご覧ください。"
        text = direction + exclusion + " 総務部 " + "所在地 " * 40 + "info@issuer.co.jp"
        _, quote = self.source("spaced_exclusion", text=text, title="お問い合わせ")
        record = self.reviewed(self.record([quote], level="ir_email_verified", emails=["info@issuer.co.jp"]))
        result, validator = self.check(record)
        self.assertTrue(result["channel_verified"], validator.issues)
        # A positive instruction to contact recruitment at this address does
        # not exclude recruitment and must not inherit the preceding IR scope.
        recruitment_route = "なお、採用に関するお問い合わせは、 採用担当宛て にご連絡ください。"
        _, quote = self.source("spaced_exclusion", text=text.replace(exclusion, recruitment_route), title="お問い合わせ")
        record["evidence"] = [quote]
        self.assertFalse(self.check(record)[0]["channel_verified"])

    @staticmethod
    def protected_href(value):
        key = 0x17
        raw = value.encode("utf-8")
        return "https://issuer.co.jp/cdn-cgi/l/email-protection#" + bytes([key, *(byte ^ key for byte in raw)]).hex()

    def test_public_protected_address_derivation_replays_and_keeps_ir_scope(self):
        href = self.protected_href("contact@issuer.co.jp?subject=質問")
        recruit_href = self.protected_href("recruit@issuer.co.jp")
        _, parent = self.source("ir_parent", text="IRお問い合わせ", url="https://issuer.co.jp/ir/",
                                links=[{"url": "https://issuer.co.jp/contact", "label": "IRお問い合わせ"}])
        text = "株式会社に関するお問い合わせは [email protected] 求人・採用に関するお問い合わせは [email protected]"
        _, contact = self.source("protected", text=text, url="https://issuer.co.jp/contact", title="お問い合わせ",
                                 links=[{"url": href, "label": "[email protected]"},
                                        {"url": recruit_href, "label": "[email protected]"}])
        contact.update(quote="株式会社に関するお問い合わせは [email protected]", source_link_url=href)
        record = self.reviewed(self.record([parent, contact], level="ir_email_verified", emails=["contact@issuer.co.jp"]))
        record["manual_review"]["public_email_derivation"] = {
            "method": "cloudflare_email_protection_public_href_xor", "snapshot": contact["snapshot"],
            "encoded_href": href, "decoded_address": "contact@issuer.co.jp", "decode_steps": "Hex, first-byte XOR, UTF-8, address before ?."}
        result, validator = self.check(record)
        self.assertTrue(result["channel_verified"], validator.issues)
        self.assertEqual(validation.decode_cloudflare_email(href), "contact@issuer.co.jp")
        record["manual_review"]["public_email_derivation"]["decoded_address"] = "fake@issuer.co.jp"
        self.assertFalse(self.check(record)[0]["channel_verified"])
        record["manual_review"]["public_email_derivation"].update(encoded_href=recruit_href, decoded_address="recruit@issuer.co.jp")
        contact["source_link_url"] = recruit_href; record["public_ir_emails"] = ["recruit@issuer.co.jp"]
        self.assertFalse(self.check(record)[0]["channel_verified"])

    def test_current_seed_snapshot_takes_precedence_with_legacy_fallback(self):
        # An obsolete cache may have an incompatible envelope; a validated
        # current-universe array must be the source actually examined.
        (self.root / "seeds.json").write_text(json.dumps({"old_cache": []}), encoding="utf-8")
        (self.root / "seeds-current.json").write_text(json.dumps([
            {"security_code": "1301", "official_url": "https://issuer.co.jp/"}]), encoding="utf-8")
        report = validation.SurveyValidator(self.root, self.universe).run()
        self.assertEqual(report["error_count"], 0)
        (self.root / "seeds-current.json").unlink()
        with self.assertRaisesRegex(ValueError, "seeds.json must contain an array"):
            validation.SurveyValidator(self.root, self.universe).run()

