    def anchored_personal_form_fixture(self, mode="valid"):
        page = "https://issuer.co.jp/inq_personal.html"
        selector = "個人のお客様のお問合せ お問合せは以下フォームよりお問合せ下さい。 入力前にお問い合わせ内容を選択 して下さい。 選択して下さい。 ご意見・ご要望 IRに関して FC募集に関して"
        stock_text = "E-mail（※） 株主確認（※） 当社の株式を所有していない。 当社の株式を所有している。 株主名簿と照合の上、回答します。 お問合せ内容（※）"
        fields = {"text": stock_text, "method": "post", "action": "confirm_personal_2.html",
                  "controls": [{"tag": "input", "type": "text", "name": "form2_mail"},
                               {"tag": "input", "type": "radio", "name": "form2_stock"},
                               {"tag": "textarea", "name": "form2_content"}]}
        forms = [{**QUESTION_FORM, "action": "confirm_personal_1.html", "text": "店舗 " + QUESTION_FORM["text"]}, fields,
                 {**QUESTION_FORM, "action": "confirm_personal_3.html", "text": "FC募集 " + QUESTION_FORM["text"]}]
        anchor = "inqform3" if mode == "wrong_anchor" else "inqform2"
