        label = "お問い合わせ" if mode == "ordinary_link" else "IRに関して"
        if mode == "wrong_action":
            fields["action"] = "confirm_personal_3.html"
        if mode == "split_controls":
            forms[0]["controls"] = [fields["controls"][0], *QUESTION_FORM["controls"]]
            fields["controls"] = fields["controls"][1:]
        if mode == "other_form_quote":
            forms[0]["text"] += " " + stock_text; fields["text"] = "電話番号 お問い合わせ内容"
        if mode == "duplicate_action":
            forms.append(fields)
        _, quote = self.source("anchored_personal", text=selector + " " + stock_text, title="お問い合わせ",
                               url=page, forms=forms, links=[{"url": href, "label": label}])
        selector_entry = {**quote, "quote": selector}; stock_entry = {**quote, "quote": stock_text}
        record = self.record([selector_entry, stock_entry]); record["individual_access"] = "explicit"
        if mode == "uncited_selector":
            record["evidence"] = [stock_entry]
        if mode == "uncited_stock":
            record["evidence"] = [selector_entry]
        return record

