    def named_ir_tab_fixture(self, mode="valid"):
        instruction = ("会社情報・IR情報・製品・その他お問い合わせについては下記のメールフォームをご利用ください。"
                       "なお、お問い合わせの際には、ご用件に合ったメールフォームをご利用ください。")
        tabs = "IRに関するお問い合わせ 製品に関するお問い合わせ その他のお問い合わせ"
        field_texts = ["お名前 メールアドレス 件名 お問い合わせ内容",
                       "御社名 メールアドレス 種別選択 製品のお問い合わせ内容",
                       "メールアドレス 採用情報に関して その他ご質問 お問い合わせ内容"]
        forms = [{"method": "post", "action": "/ir/contact#tab-" + prefix,
                  "text": text,
                  "controls": [{"tag": "input", "type": "email", "name": prefix + "-email"},
                               {"tag": "textarea", "name": prefix + "-message"}]}
                 for prefix, text in zip(("ir", "product", "other"), field_texts)]
        if mode == "navigation_only":
            instruction = "企業情報 IR情報 製品情報 お問い合わせ"
        elif mode == "privacy_only":
            instruction = "個人情報保護方針 IRへのお問い合わせを含む利用目的"
        elif mode == "deflection":
            instruction = "IR情報については決算資料をご覧ください。製品については下記フォームをご利用ください。"
        elif mode == "unrelated_tabs":
            tabs = "製品に関するお問い合わせ 採用に関するお問い合わせ その他のお問い合わせ"
        elif mode == "split_controls":
            forms[1]["controls"].append(forms[0]["controls"].pop())
        elif mode == "hidden_reply":
            forms[0]["controls"][0]["type"] = "hidden"
        elif mode == "product_field_names":
            forms[0]["controls"] = forms[1]["controls"]
        elif mode == "ambiguous_ir_forms":
            forms[2]["controls"] = forms[0]["controls"]
        elif mode == "same_post_action":
            forms[2]["action"] = forms[0]["action"]
        elif mode == "external_post_action":
            forms[0]["action"] = "https://unrelated.co.jp/inquiry#tab-ir"
        text = instruction + " " + tabs + " " + " ".join(field_texts)
        if mode == "wrong_order":
            text = " ".join(field_texts) + " " + instruction + " " + tabs
        source, base = self.source("named_ir_tabs", text=text, title="お問い合わせ", forms=forms)
        source["headings"] = ["お問い合わせ", "お問い合わせ用メールフォーム", "プライバシーポリシー"]
        if mode == "missing_heading":
            source["headings"] = ["お問い合わせ", "プライバシーポリシー"]
        (self.root / base["snapshot"]).write_text(json.dumps(source), encoding="utf-8")
        entries = [{**base, "quote": instruction}, {**base, "quote": tabs},
                   {**base, "quote": field_texts[1] if mode == "other_form_quote" else field_texts[0]}]
        if mode == "uncited_instruction":
            entries.pop(0)
        elif mode == "uncited_tabs":
            entries.pop(1)
        elif mode == "uncited_fields":
            entries.pop(2)
        record = self.record(entries)
        if mode == "other_url":
            record["contact_url"] = "https://issuer.co.jp/product/contact"
        return record

