    def long_ir_consent_mail_section_fixture(self, mode="valid"):
        heading = "当社IRに関するお問い合わせ"
        consent = "以下の内容についてご同意いただける方は「同意します」をクリックしてお問い合わせ下さい。"
        padding = ("①お問い合わせの内容・時期によりご回答までお時間をいただく場合がございます。 "
                   "②決算日から決算発表日までを沈黙期間とし、当該期間中は回答を差し控えております。 "
                   "③非開示情報や株価に関するお問い合わせには回答を差し控えております。 "
                   "④当社回答の転載・二次利用はご遠慮ください。 ") * 4
        fallback = "［ 同意します ］ クリックでメーラーが起動します。起動しない場合は ir@issuer.co.jp に直接ご連絡ください。"
        section = heading + " " + consent + " " + padding + fallback
        next_heading = "取材・広報に関するお問い合わせ"
        other_rows = [("ビジネスパートナーのお問い合わせ", "partner@issuer.co.jp"),
                      ("一般のお問い合わせ", "info@issuer.co.jp"), (next_heading, "pr@issuer.co.jp")]
        other_sections = [h + " " + consent + " " + padding + fallback.replace("ir@issuer.co.jp", a) for h,a in other_rows]
        body = other_sections[0] + " " + other_sections[1] + " " + section + " " + other_sections[2]
        headings = [other_rows[0][0], other_rows[1][0], heading, next_heading]
        links = [{"label": "［ 同意します ］", "url": "mailto:" + address} for address in
                 ("partner@issuer.co.jp", "info@issuer.co.jp", "ir@issuer.co.jp", "pr@issuer.co.jp")]
        quote, email = section, "ir@issuer.co.jp"
        if mode in ("partner_recipient", "general_recipient", "press_recipient"):
            index = {"partner_recipient":0, "general_recipient":1, "press_recipient":2}[mode]
            quote, email = other_sections[index], other_rows[index][1]
        elif mode == "partial_quote": quote = fallback
        elif mode == "uncited_fallback": quote = heading + " " + consent
        elif mode == "heading_only_in_navigation": headings.remove(heading)
        elif mode == "duplicate_heading": body += " " + heading
        elif mode == "duplicate_next_heading": body += " " + next_heading
        elif mode == "next_heading_between_scope_and_address":
            # Move the actual next section before the IR fallback, leaving a
            # single next heading and a quote that crosses that boundary.
            quote = section.replace(fallback, next_heading + " " + fallback)
            body = other_sections[0] + " " + other_sections[1] + " " + quote + " " + other_sections[2].replace(next_heading, "広報窓口",1)
            headings.append("広報窓口")
        elif mode == "no_actual_mailto": links.pop(2)
        elif mode == "generic_link_label": links[2]["label"] = "メールを送信"
        elif mode == "duplicate_link": links.append(links[2].copy())
        elif mode == "input_example":
            quote = section.replace(fallback, "入力例： " + fallback); body = body.replace(section,quote)
        elif mode == "phone_only":
            quote = section.replace(consent, consent + " IRのお問い合わせは電話のみです。"); body = body.replace(section,quote)
        _, base = self.source("long_ir_section", text=body, title="お問い合わせ", links=links)
        source = json.loads((self.root / base["snapshot"]).read_text()); source["headings"] = headings
        (self.root / base["snapshot"]).write_text(json.dumps(source),encoding="utf-8")
        base["quote"] = quote
        if mode != "uncited_mailto": base["source_link_url"] = "mailto:" + ("pr@issuer.co.jp" if mode == "wrong_mailto" else email)
        record = self.record([base],level="ir_email_verified",emails=[email])
        if mode == "another_url": record["contact_url"] = "https://issuer.co.jp/press/"
        return record

