    def identity_from_listing_fixture(self, text, *, code="1301", failed=False, controls=None):
        snapshot="evidence/listing_identity.json"
        source={"requested_url":"https://issuer.co.jp/investors/contact/",
                "url":"https://issuer.co.jp/investors/contact/","http_status":503 if failed else 200,
                "text":text,"title":"IRに関するお問い合わせ | 略称",
                "forms":[] if controls is None else [{"controls":controls}],
                "links":[],"submitted":False,"retrieved_at":STAMP}
        (self.root/snapshot).write_text(json.dumps(source))
        universe={code:{"company_name":"完全正式会社名株式会社","market":"プライム（内国株式）"}}
        validator=validation.SurveyValidator(self.root,universe)
        record={"security_code":code,"company_name":"完全正式会社名株式会社",
                "investigation_status":"confirmed","identity_status":"name_or_security_code_observed",
                "identity_matches":[{"snapshot":snapshot}]}
        validator.identity(record,None)
        return validator

    def test_public_company_listing_declaration_with_balanced_quoted_code_proves_identity(self):
        for code in ("1301","130A"):
            with self.subTest(code=code):
                sentence='当社は東京証券取引所に上場しており、証券コードは「'+code+'」です。'
                text="上場市場を教えてください。 "+sentence+" <p>"+sentence+"</p>"
                self.assertEqual(self.identity_from_listing_fixture(text,code=code).issues,[])
        for text in ("証券コード：1301", "銘柄コード 1301", "Security code: 1301"):
            with self.subTest(legacy=text):
                self.assertEqual(self.identity_from_listing_fixture(text).issues,[])

    def test_listing_identity_rejects_other_code_unbalanced_quote_nonissuer_and_hidden_only(self):
        sentence='当社は東京証券取引所に上場しており、証券コードは「1301」です。'
        negatives=[sentence.replace("1301","1302"),sentence.replace("1301","13015"),
                   sentence.replace("1301","1301A"),sentence.replace("1301","A1301"),
                   sentence.replace('「1301」','「1301'),sentence.replace('「1301」','1301」'),
                   sentence.replace('「1301」','「1301』'),sentence.replace('「1301」','『1301」'),
                   sentence.replace('「1301」','「1301 1302」'),sentence.replace('「1301」','「1301,1302」'),
                   sentence.replace("当社は","同業他社は"),sentence.replace("上場しており","上場しておらず"),
                   sentence.replace("証券コードは","証券コードではなく"),"証券コードは「1301」です。",
                   "IR情報 お問い合わせ 略称 Inc. 1301"]
        for text in negatives:
            with self.subTest(text=text):
                self.assertEqual([i["kind"] for i in self.identity_from_listing_fixture(text).issues],["identity_basis"])
        self.assertEqual([i["kind"] for i in self.identity_from_listing_fixture(sentence,failed=True).issues],["identity_basis"])
        self.assertEqual([i["kind"] for i in self.identity_from_listing_fixture("IR情報 問い合わせ 略称",controls=[
            {"tag":"input","type":"hidden","name":"code","value":sentence}]).issues],["identity_basis"])


