    def phone_difficulty_ir_consent_fixture(self, mode="valid"):
        landing="https://issuer.co.jp/contact/";target=landing+"entry.html"
        faq='IRに関する問い合わせはどこに連絡すればよいですか？ IRに関するお問い合わせは、原則「03-1234-5678」（IR専用電話）へお電話をお願いいたします。但し、聴覚障がい等の方は、「 お問い合わせ 」をご利用ください。'
        if mode=="general_parent":faq='一般のお問い合わせは電話でお願いします。「 お問い合わせ 」をご利用ください。'
        elif mode=="ir_navigation_parent":faq="IR情報 お問い合わせ"
        parent_target=landing+"?type=patient" if mode=="other_parent_target" else landing
        _,parent=self.source("phone_difficulty_ir_parent",text=faq,title="よくあるご質問｜IR情報",url="https://issuer.co.jp/ir/faq.html",links=[{"label":"お問い合わせ","url":parent_target}])
        parent["source_link_url"]=parent_target
        if mode=="uncited_parent_target":parent.pop("source_link_url")
        policy="IRに関するお問い合わせは原則お電話で承ります。お電話が困難な方のみお問い合わせフォームより承ります。"
        label="上記に同意してフォームに進む"
        if mode=="ordinary_phone":policy="お問い合わせは原則お電話で承ります。お電話が困難な方はお問い合わせフォームもご利用ください。"
        elif mode=="patient_phone_only":policy=policy.replace("IRに関するお問い合わせ","患者様のお問い合わせ")
        elif mode=="privacy_only":policy=policy.replace("IRに関するお問い合わせ","個人情報に関するお問い合わせ")
        elif mode=="form_open_to_all":policy=policy.replace("方のみ","方も")
        elif mode=="phone_no_form":policy="IRに関するお問い合わせはお電話で承ります。"
        link_target=landing+"entry.html?type=patient" if mode=="other_entry_query" else target
        if mode=="cross_host_entry":link_target="https://other.co.jp/contact/entry.html"
        elif mode=="same_page_entry":link_target=landing
        links=[{"label":label,"url":link_target}]
        if mode=="no_entry_link":links=[]
        elif mode=="duplicate_entry_link":links.append(links[0].copy())
        elif mode=="general_link":links[0]["label"]="お問い合わせ"
        search={"method":"get","text":"検索","controls":[{"tag":"input","type":"search","name":"q"}]}
        body="お問い合わせフォームからのお問い合わせ お問い合わせに当たってのご注意事項 "+policy+" "+label
        if mode=="duplicate_policy":body+=" "+policy
        elif mode=="policy_after_consent":body=label+" "+body.replace(" "+label,"")
        elif mode=="response_delay":body+=" 回答にお時間をいただく場合があります。適切に対応するため、お電話による回答を行う場合があります。"
        _,base=self.source("phone_difficulty_consent",text=body,title="お問い合わせ",url=landing,forms=[search],links=links)
        p=self.root/base["snapshot"];saved=json.loads(p.read_text());saved["headings"]=["お問い合わせ","お問い合わせフォームからのお問い合わせ","お問い合わせに当たってのご注意事項"]
        if mode=="no_notice_heading":saved["headings"]=["お問い合わせ"]
        elif mode=="failed_policy_page":saved["http_status"]=503
        p.write_text(json.dumps(saved))
        entries=[parent]
        if mode!="uncited_policy":entries.append({**base,"quote":policy,"role":"restriction_basis"})
        entry={**base,"quote":label,"source_link_url":link_target,"role":"official_consent_link"}
        if mode=="uncited_entry_target":entry.pop("source_link_url")
        elif mode=="wrong_cited_entry":entry["source_link_url"]=target+"?type=product"
        entries.append(entry)
        if mode=="missing_parent":entries.pop(0)
        record=self.reviewed(self.record(entries,level="official_form_link_only"))
        record["investigation_status"]="provisional";record["contact_url"]=target
        record["individual_access"]="restricted";record["outreach_suitability"]="restricted"
        if mode=="wrong_contact_url":record["contact_url"]=target+"?type=product"
        elif mode=="unreviewed":record["manual_review_required"]=True;record.pop("manual_review")
        return record

