    def test_ir_desk_proof_keeps_exact_quote_url_aware_time_and_readonly_source_binding(self):
        for kind in ("quote_mismatch","evidence_url","evidence_time","submission_flag"):
            with self.subTest(kind=kind):
                record=self.ir_desk_multiform_fixture()
                for e in record["evidence"]:
                    if kind=="quote_mismatch":e["quote"]="Unobserved IR form fields"
                    elif kind=="evidence_url":e["url"]+="?type=other"
                    elif kind=="evidence_time":e["retrieved_at"]="2026-10-11T01:00:00"
                    else:
                        p=self.root/e["snapshot"];saved=json.loads(p.read_text());saved["submitted"]=True;p.write_text(json.dumps(saved))
                result,validator=self.check(record)
                self.assertFalse(result["channel_verified"])
                self.assertIn(kind,[i["kind"] for i in validator.issues])

