        """Exercise bound evidence and native mutations, without live sources."""
        entries = record["evidence"]; form = source["forms"][0]; controls = form["controls"]
        full = next(e for e in entries if e.get("source_form_index") == 0 and e.get("extraction_scope") is None)
        choice = layout["choice"]; choice_e = next((e for e in entries if e["quote"] == choice), None)
        attr = next((e for e in entries if e.get("extraction_scope")), None)
        selected, reply, question = layout["selection"], layout["reply"], layout["question"]
        if mode == "hidden_selection": controls[selected]["type"] = "hidden"
        elif mode == "search_selection": controls[selected]["tag"] = "input"; controls[selected]["type"] = "search"
        elif mode == "generic_selection": controls[selected]["name"] = "customer"
        elif mode == "checkbox_selection": controls[selected]["tag"] = "input"; controls[selected]["type"] = "checkbox"
        elif mode == "missing_selection": controls.pop(selected)
        elif mode == "reordered_selection": other = layout.get("reorder_selection_with", (selected + 1) % len(controls)); controls[selected], controls[other] = controls[other], controls[selected]
        elif mode == "duplicate_selection": controls.insert(selected, dict(controls[selected]))
        elif mode == "hidden_reply": controls[reply]["type"] = "hidden"
        elif mode == "search_reply": controls[reply]["type"] = "search"
        elif mode == "generic_reply": controls[reply]["name"] = "customer"
        elif mode == "wrong_reply_id": controls[reply]["id"] = "customer"
        elif mode == "wrong_reply_placeholder": controls[reply]["placeholder"] = "お客様番号"
        elif mode == "reordered_reply": controls[reply], controls[reply - 1] = controls[reply - 1], controls[reply]
        elif mode == "missing_confirmation": controls.pop(layout["confirmation"])
        elif mode == "hidden_confirmation": controls[layout["confirmation"]]["type"] = "hidden"
        elif mode == "hidden_question": controls[question]["type"] = "hidden"
        elif mode == "input_question": controls[question]["tag"] = "input"; controls[question]["type"] = "text"
        elif mode == "generic_question": controls[question]["name"] = "customer"
        elif mode == "auxiliary_question": controls[question]["name"] = layout.get("auxiliary", "comments")
        elif mode == "split_question": question_control = controls.pop(question); source["forms"].append({"method": "post", "text": "お問い合わせ内容", "controls": [question_control]})
        elif mode == "native_zero": form["controls"] = []
        elif mode == "get_form": form["method"] = "get"
        elif mode == "wrong_action": form["action"] = "https://other.co.jp/submit"
        elif mode == "action_query": form["action"] = form["action"].split("#")[0] + "?kind=products"
        elif mode == "second_question_form": source["forms"].append(dict(QUESTION_FORM))
        elif mode == "wrong_requested_url": source["requested_url"] += "?kind=products"
        elif mode == "source_query": source["url"] = source["requested_url"] = source["url"] + "?kind=products"
        elif mode == "wrong_source_host": source["url"] = source["requested_url"] = source["url"].replace("issuer.co.jp", "other.co.jp")
        elif mode == "uncited_full": entries.remove(full)
        elif mode == "truncated_full": full["quote"] = full["quote"][:50]
        elif mode == "wrong_source_index": full["source_form_index"] = 1
        elif mode == "string_source_index": full["source_form_index"] = "0"
        elif mode == "boolean_source_index": full["source_form_index"] = False
        elif mode == "missing_source_index": full.pop("source_form_index")
        elif mode == "contradictory_index": full["form_index"] = 1
        elif mode == "uncited_choice": entries.remove(choice_e)
        elif mode == "choice_in_nav": form["text"] = form["text"].replace(choice, "別の項目", 1); source["extra"] = choice
        elif mode == "choice_in_policy": form["text"] = form["text"].replace(choice, "別の項目", 1) + " プライバシー資料 " + choice
        elif mode == "choice_other_form": form["text"] = form["text"].replace(choice, "別の項目", 1); source["forms"].append({"method": "post", "text": choice, "controls": [{"tag": "select", "name": "customer"}]})
        elif mode == "generic_choice": form["text"] = form["text"].replace(choice, "一般のお客様 法人 個人", 1)
        elif mode == "personal_refused": form["text"] += " 個人投資家は受け付けません。"
        elif mode == "parent_other_host": parent["url"] = parent["requested_url"] = parent["url"].replace("issuer.co.jp", "other.co.jp")
        elif mode == "parent_failed": parent["http_status"] = 404
        elif mode == "parent_no_link": parent["links"] = []
        elif mode == "parent_query": parent["links"][layout.get("parent_link", 0)]["url"] += "?kind=products"
        elif mode == "parent_encoded_raw": link = parent["links"][layout.get("parent_link", 0)]; raw = "src" if family == "numeric" else "href"; link[raw] = link[raw].replace("/", "/%2F", 1)
        elif mode == "parent_generic_label": parent["links"][layout.get("parent_link", 0)]["label"] = "お問い合わせ"
        elif mode == "parent_product_title": parent["title"] = "製品・サービス | Other株式会社"
        elif mode == "parent_nav_only": parent["headings"] = ["IR情報", "お問い合わせ"]
        elif mode == "wrong_parent_index": next(e for e in entries if "source_link_index" in e)["source_link_index"] = 0
        elif mode == "boolean_parent_index": next(e for e in entries if "source_link_index" in e)["source_link_index"] = True
        elif mode == "missing_parent_index": next(e for e in entries if "source_link_index" in e).pop("source_link_index")
        elif mode == "uncited_parent": entries[:] = [e for e in entries if e["snapshot"] != layout["parent_snapshot"]]
        elif mode == "uncited_parent_title": entries[:] = [e for e in entries if not (e["snapshot"] == layout["parent_snapshot"] and e["quote"] == parent["title"])]
        elif mode == "uncited_child_title": entries[:] = [e for e in entries if not (e["snapshot"] == full["snapshot"] and e["quote"] == source["title"])]
        elif mode == "fake_ir": parent["headings"] = ["製品情報"]; parent["text"] = "IR情報 お問い合わせ 製品・サービス Fixture株式会社"; entries[:] = [e for e in entries if e["snapshot"] != layout["parent_snapshot"]]
        elif mode == "product_only": form["text"] = form["text"].replace(layout["financial_word"], "製品・サービス", 1)
        elif mode == "duplicate_full_text": source["extra"] = form["text"]
        elif mode == "required_company_removed": controls[0].pop("required", None)
        elif mode == "company_placeholder_removed": controls[layout["company"]].pop("placeholder")
        elif mode == "hidden_company": controls[layout["company"]]["type"] = "hidden"
        elif mode == "attribute_value": controls[layout["company"]]["value"] = controls[layout["company"]].pop("placeholder"); attr["field_path"] = attr["field_path"].replace("placeholder", "value")
        elif mode == "attribute_wrong_scope": attr["extraction_scope"] = "page_attribute"
        elif mode == "attribute_wrong_path": attr["field_path"] = "forms.0.controls.2.placeholder"
        elif mode == "attribute_wrong_index": attr["source_form_index"] = 1
        elif mode == "attribute_string_index": attr["source_form_index"] = "0"
        elif mode == "attribute_boolean_index": attr["source_form_index"] = False
        elif mode == "attribute_missing_index": attr.pop("source_form_index")
        elif mode == "uncited_attribute": entries.remove(attr)
        elif mode == "parent_borrowed_identity": entries[:] = [e for e in entries if not (e["snapshot"] == layout["parent_snapshot"] and e["quote"].startswith("証券コード:"))]
        if mode not in {"uncited_full", "truncated_full"}: full["quote"] = form["text"]
        source["text"] = source["title"] + " " + layout.get("outside", "") + " " + form["text"] + " Fixture株式会社 " + source.pop("extra", "")
        for e in entries:
            if e["snapshot"] == full["snapshot"]: e["url"] = source["url"]
            elif e["snapshot"] == layout["parent_snapshot"]: e["url"] = parent["url"]
        record["contact_url"] = source["url"]
        if mode == "wrong_claim_url": record["contact_url"] += "?kind=products"
        elif mode == "unreviewed": record["manual_review_required"] = True
        elif mode == "no_reply_claim": record["outreach_suitability"] = "no_individual_reply"
        elif mode == "personal_claim": record["individual_access"] = "explicitly_allowed"
        (self.root / full["snapshot"]).write_text(json.dumps(source)); (self.root / layout["parent_snapshot"]).write_text(json.dumps(parent))
        return record

