    def finite_native_reception_check(self, record):
        v = validation.SurveyValidator(self.root, self.universe)
        result = v.validate_record(record, {"official_url":record["official_url"]})
        return result, v

    def test_finite_policy_checkboxes_complete_native_ir_witness(self):
        record = self.finite_native_reception_fixture('policy_checkboxes')
        result, v = self.finite_native_reception_check(record)
        self.assertEqual(v.issues, [])
        self.assertTrue(result["channel_verified"])
        self.assertEqual(result["outreach_suitability"], "candidate")
        self.assertEqual(result["individual_access"], 'not_stated')
        self.assertEqual(record["public_ir_emails"], [])
        pairs = v.evidence(record)
        source = next(s for e,s in pairs if e.get("source_form_index") == 0 and e["quote"] == s["forms"][0]["text"])
        self.assertTrue(v.reviewed_ir_checkbox_after_long_policy(record, source, pairs))
        form = source["forms"][0]
        self.assertEqual(form["method"], 'post')
        self.assertEqual(form["action"], '/mhd/contacthd/#wpcf7-f8-p16-o1')
        self.assertFalse(any("required" in control for control in form["controls"]))
        self.assertEqual(form["controls"][2]["tag"], "input")
        self.assertEqual(form["controls"][12]["tag"], "textarea")

