    def six_category_opaque_ir_fixture(self, mode="valid"):
        """A complete mixed-use questionnaire and a separately captured financial parent."""
        import copy
        (self.root / "evidence/1301").mkdir(exist_ok=True)
        self.universe["1301"]["company_name"] = "Fixture"
        official = "https://issuer.co.jp/"
        target = official + "contact/"
