    def test_six_category_opaque_questionnaire_needs_its_actual_financial_route(self):
        record = self.six_category_opaque_ir_fixture()
        result, validator = self.check(record)
        self.assertEqual([], validator.issues)
        self.assertTrue(result["channel_verified"])
        self.assertEqual("not_stated", result["individual_access"])
        source = validator.load_snapshot(record["evidence"][0]["snapshot"], "1301")
        form = source["forms"][0]
        self.assertFalse(validation.question_form(form))
        self.assertFalse(validation.reviewed_question_form(form))
        self.assertEqual("text", form["controls"][16]["type"])
        self.assertTrue(all("required" not in c for c in form["controls"]))
        self.assertTrue(all("value" not in c for c in form["controls"][:6]))
        self.assertIn("ご利用のメールソフトにメールが自動で作成されます", record["conditions"][0])
        self.assertEqual("post", form["method"])

