            "wrong_source_host", "wrong_source_scheme", "wrong_source_path", "wrong_source_query", "wrong_source_fragment", "wrong_requested", "redirected_source", "failed_source", "boolean_status", "error_source", "submitted_source", "wrong_source_title", "wrong_source_headings", "naive_source_time",
            "wrong_quote_time", "wrong_quote_url", "wrong_full_quote", "partial_full_quote", "no_full_quote", "legacy_index_only", "bool_source_index", "string_source_index", "wrong_source_index", "bool_legacy_index", "string_legacy_index", "wrong_legacy_index",
            "no_choice_quote", "missing_choice_index", "bool_choice_index", "string_choice_index", "wrong_choice_index", "no_identity_quote", "identity_on_other_source", "no_operation_quote", "partial_operation_quote", "operation_in_footer", "form_in_privacy", "form_in_product", "duplicate_full_quote",
            "primary_not_fetched", "primary_fetch_wrong_time", "primary_fetch_other_issuer_prefix", "fields_on_other_source", "wrong_form_method", "missing_form_method", "wrong_form_action", "wrong_action_host", "wrong_action_scheme", "missing_form_action", "search_form_first", "duplicate_native_form", "no_native_form",
            "missing_radio", "extra_radio", "radio_is_checkbox", "radio_is_hidden", "wrong_radio_name", "hidden_reply", "search_reply", "inferred_email_type", "wrong_reply_name", "hidden_question", "question_is_input", "wrong_question_name", "question_reply_swapped", "person_question_swapped", "control_order_reversed", "inferred_company_required", "inferred_reply_required", "extra_hidden_control",
            "wrong_public_reply_label", "reply_label_in_policy", "no_actual_ir_choice", "ir_value_only", "ir_in_navigation_only", "ir_in_privacy_only", "ir_customer_service", "ir_refused", "individual_refused",
