    def test_six_category_ir_form_keeps_personal_reply_and_fallback_email_limits(self):
        for mode, error in (("explicit_individual_claim", "individual_access_basis"),
                            ("blanket_no_reply_claim", "reply_policy_basis"),
                            ("fallback_ir_email_claim", "email_unattributed")):
            with self.subTest(mode=mode):
                result, validator = self.check(self.six_category_opaque_ir_fixture(mode))
                self.assertFalse(result["channel_verified"])
                self.assertIn(error, [issue["kind"] for issue in validator.issues])



