    def assert_captured_ir_negative_family(self, family):
        for mode in self.captured_ir_negative_modes(family):
            with self.subTest(family=family, mode=mode):
                result, validator = self.check(self.captured_ir_reception_fixture(family, mode))
                self.assertFalse(result["channel_verified"])
                self.assertTrue({"form_level", "individual_access_basis", "identity_unverified", "manual_review_missing"}.intersection(i["kind"] for i in validator.issues))

    def assert_captured_ir_positive_family(self, family):
        record = self.captured_ir_reception_fixture(family)
        original_identity = (record["identity_status"], list(record["identity_matches"]))
        result, validator = self.check(record)
        self.assertTrue(result["channel_verified"])
        self.assertEqual(0, result["error_count"])
        self.assertEqual(["company_field_unresolved"] if family == "consent" else [], [i["kind"] for i in validator.issues])
        self.assertEqual(original_identity, (record["identity_status"], record["identity_matches"]))
        self.assertEqual([], record["public_ir_emails"])
        self.assertEqual("candidate", result["outreach_suitability"])
        self.assertEqual("explicitly_allowed" if family in {"company", "bilingual"} else "explicit" if family == "department" else "not_stated", result["individual_access"])

